def nibble(w, which):
    return (w >> (4*which)) & 0xF

def decode_extra(dex, op, fmt, words, pc):
    w0=words[0]
    aa = (w0>>8)&0xFF
    a_n = (w0>>8)&0xF
    b_n = (w0>>12)&0xF
    if fmt=="10x":
        return ""
    if fmt=="11x":
        return f"v{aa}"
    if fmt=="11n":
        lit = a_n
        if lit & 0x8:
            lit -= 16
        return f"v{b_n}, #{lit}"
    if fmt=="12x":
        return f"v{a_n}, v{b_n}"
    if fmt=="10t":
        off = struct.unpack("b", bytes([aa if aa<128 else aa]))[0] if False else (aa if aa<128 else aa-256)
