    if fmt=="22s":
        lit = struct.unpack("<h", struct.pack("<H", words[1]))[0]
        return f"v{a_n}, v{b_n}, #{lit}"
    if fmt=="22b":
        bb=words[1]&0xFF
        cc=(words[1]>>8)&0xFF
        lit = cc if cc<128 else cc-256
        return f"v{aa}, v{bb}, #{lit}"
    if fmt=="22c":
        idx=words[1]
        if op in (0x20,0x23):
            return f"v{a_n}, v{b_n}, {dex.type_name(idx)}"
        if 0x52<=op<=0x5f:
            c,n,t = dex.field(idx)
            return f"v{a_n}, {c}->{n}:{t}"
        return f"v{a_n}, v{b_n}, id@{idx}"
